var CONV_T = window.CONV_T || {}; CONV_T["ru"] = {"twoOverOne":["2/1 форсинг до гейма","Из непасовавшей руки новая масть на уровне двух после открытия партнёра на уровне одного (кроме 1♣–2♦; 1♠–2♥ показывает пять червей) — форсинг до гейма, 12+ О. На 1♥/1♠ ответ 1БК — форсинг на круг (6-12 О): открывший при отсутствии иного называет третью младшую; последующий прыжок отвечающего на 3 в мажоре показывает инвитную поддержку из трёх карт. Ответ на уровне двух из пасовавшей руки не форсирующий."],"rkc":["RKCB 1430","4БК спрашивает пять ключевых карт (четыре туза + король козыря). 5♣ = 1 или 4, 5♦ = 3 или 0, 5♥ = 2 без дамы козыря, 5♠ = 2 с дамой козыря."],"rkc0314":["RKCB 0314","4БК спрашивает пять ключевых карт (четыре туза + король козыря). 5♣ = 0 или 3, 5♦ = 1 или 4, 5♥ = 2 без дамы козыря, 5♠ = 2 с дамой козыря. Вместо RKCB 1430."],"gerber":["Гербер","После 1БК, 2БК или 3БК партнёра, без согласованной масти, 4♣ спрашивает тузы. 4♦ = 0 или 4, 4♥ = 1, 4♠ = 2, 4БК = 3. Спрашивающий может остановиться в 4БК."],"bergen":["Повышения Бергена","На 1♥/1♠ (не после контры или вмешательства): 3♣ = поддержка из четырёх карт, 7-9 очков; 3♦ = четыре карты, 10-12 (инвит); 3 в мажоре = четыре карты, 0-6 (блок). С четырьмя картами и 13+ — Якоби 2БК или сплинтер. Простое повышение показывает три карты, 6-9; инвит с тремя картами идёт через форсирующие 1БК."],"capp":["Каппеллетти","Против 1БК соперников (в прямой позиции): X = штрафная, 15+ О. 2♣ = одномастка (6+ карт): партнёр спрашивает 2♦, вмешавшийся пасует с бубнами или называет масть. 2♦ = обе старшие (5-4 и длиннее): партнёр выбирает мажор (прыжок — инвит, 10-12). 2♥/2♠ = 5+ в этом мажоре и младшая из 4+: партнёр пасует, повышает или спрашивает младшую через 2БК. 2БК = обе младшие (5-5): партнёр выбирает."],"j2nt":["Якоби 2БК","2БК на открытие в мажоре = поддержка из 4+ карт, 13+ очков, форсинг до гейма. Открывший: 3 в новой масти = синглет или ренонс; 4 в новой масти = хорошая боковая пятёрка; 3 в мажоре = 18+ без коротких; 3БК = 15-17 без коротких; 4 в мажоре = минимум."],"wjs":["Слабые прыжки","Одинарный прыжок отвечающего в новой масти (напр. 1♦–2♠, 1♣–2♥) показывает масть из 6+ карт и слабую руку (0-5 О). Это игровая заявка; открывший пасует. Не после контры соперника."],"stayman":["Стейман","2♣ после 1БК (3♣ после 2БК) спрашивает четвёртый мажор. Ответы: ♦ = нет четвёртого мажора, ♥ = четыре червы, ♠ = четыре пики и не четыре червы. После 2♦ 2♥/2♠ = пять в этом мажоре + четыре в другом, инвит. Если отвечающий говорит БК на 2♥, открывший с четырьмя пиками называет и их."],"minorTr":["Минорный трансфер","После 1БК: 2♠ → трефы (открывший говорит 3♣), 3♣ → бубны (открывший говорит 3♦). Слабая рука с шестикарточным минором играет на трёх; 2БК остаётся естественным инвитом."],"fourWay":["Четырёхсторонние трансферы","После 1БК: 2♦ → червы, 2♥ → пики (Якоби), 2♠ → трефы (открывший говорит 3♣), 2БК → бубны (открывший говорит 3♦). Равномерные инвиты идут через 2♣ Стейман."],"puppet":["Паппет Стейман","После 2БК 3♣ спрашивает о 4- или 5-карточном мажоре (вместо Стеймана). Ответы: 3♦ = один или два 4-карточных мажора, 3♥ = пять червей, 3♠ = пять пик, 3БК = нет 4-карточного мажора. После 3♦ отвечающий называет мажор, которого у него нет: 3♥ = четыре пики, 3♠ = четыре червы, 4♦ = оба, 3БК = ни одного; так разыгрывает открывший 2БК."],"smolen":["Смолен","После 1БК–2♣–2♦ рука с форсингом до гейма и 5-4 в мажорах называет свой четвёртый мажор на уровне трёх: 3♥ = 4♥ + 5♠, 3♠ = 4♠ + 5♥, чтобы играла сильная рука."],"michaels":["Кью-бид Михаэльса / необычные 2БК","Прямой кью-бид их открытия на уровне одного показывает двухмастку 5-5, 7+ О: на младшую — обе старшие; на мажор — другой мажор и младшую (партнёр спрашивает младшую через 2БК). Прыжок в 2БК (необычные) показывает две младшие незаявленные масти. Партнёр выбирает; с фитом и 10+ может прыгнуть в гейм."],"splinter":["Сплинтер","Двойной прыжок в новой масти на открытие в мажоре (напр. 1♠–4♥, 1♥–3♠) = поддержка из 4+ карт, синглет или ренонс в названной масти, 11-15 О, форсинг до гейма, интерес к шлему. Открывший останавливается в 4 мажора или исследует шлем."],"texas":["Техас","После 1БК/2БК: 4♦ → 4♥, 4♥ → 4♠. Мажор из 6+ карт с силой на гейм; играет сильная рука (открывший)."],"texasInt":["Техас после вмешательства","Техас действует, когда соперники контрируют наши 1БК или вмешиваются на уровне двух-трёх: 4♦ → червы, 4♥ → пики. Заявка в их масти — не трансфер (после вмешательства 2♥ 4♥ — кью-бид, а 4♦ по-прежнему показывает червы). Открывший завершает трансфер."],"leb":["Лебензол","После вмешательства на уровне двух в наши 1БК: 2БК заставляет открывшего сказать 3♣ (чтобы остановиться в масти или показать медленно). Прямая масть на уровне трёх форсирующая. Прямые 3БК отрицают остановку; 2БК, затем 3БК — показывают. Кью-бид их масти — Стейман: прямо = без остановки, через 2БК = с остановкой («быстро — отрицает»)."],"lav":["Сносы Лавинталя","Сигналы в защите. Снесённая масть не нужна; высокая карта просит старшую из двух других мастей, низкая — младшую (козырь и сыгранная масть не считаются). На ход партнёра высокая карта поощряет, самая низкая — нет."],"roman":["Римские сносы (чёт-нечет)","Сигналы в защите. Первый снос: нечётная карта (3, 5, 7, 9) просит эту масть; чётная (2, 4, 6, 8, 10) её не хочет и просит одну из двух других мастей: младшая чётная (2, 4) — младшую, старшая (6, 8, 10) — старшую (козырь и разыгрываемая масть не в счёт). На ход партнёра высокая фоска поощряет, самая младшая — нет."],"invMin":["Обратные повышения в младших","Из непасовавшей руки на 1♣/1♦: повышение до 2 в младшей сильное (10+ очков, 4+ поддержки, 5+ в трефах, нет четвёртого мажора) и форсирует на круг; открывший с равномерным минимумом говорит 2БК, с избытком показывает остановки, с минимумом повторяет 3 в младшей. Прыжок до 3 — блок (0-9 очков, 5+ поддержки)."],"drury":["Друри","Обратный Друри. Пасовавшая рука отвечает на 1♥/1♠ партнёра в третьей/четвёртой руке 2♣ = поддержка из 3+ карт и 10-12 очков. Открывший с лёгким или минимальным открытием повторяет 2 в мажоре (без гейма), с полноценным говорит 4 в мажоре."],"nmf":["Новая младшая форсинг","После 1m–1M–1БК 2 в другой младшей у отвечающего искусственно и форсирующее (11+): спрашивает у открывшего поддержку из трёх карт в мажоре отвечающего или другой четвёртый мажор."],"fsf":["Четвёртая масть форсинг","Когда наша линия назвала три масти, заявка отвечающего в четвёртой масти искусственна и форсирует до гейма; она просит открывшего описать руку дальше (остановка, поддержка или дополнительная длина)."],"ogust":["Огуст","После слабых двух партнёра 2БК спрашивает: 3♣ = минимум, плохая масть; 3♦ = минимум, хорошая масть; 3♥ = максимум, плохая масть; 3♠ = максимум, хорошая масть; 3БК = сплошная масть (ТКД)."],"supx":["Контра поддержки","После 1m–(пас)–1M–(вмешательство ниже 2M) контра открывшего показывает ровно три карты поддержки мажора отвечающего; прямое повышение — четыре."],"respx":["Ответная контра","После их открытия, вызывной контры партнёра и их повышения контра партнёра контрирующего — вызывная: 8+ очков и обе незаявленные масти (обычно мажоры), без ясной заявки."],"sjs":["Сильные прыжки","Одинарный прыжок отвечающего в новой масти показывает сильную руку (19+ очков) с хорошей мастью и интересом к шлему. Заменяет слабые прыжки."],"dont":["DONT","Disturb Opponents’ Notrump (Марти Берген). Против их 1БК: X = одномастка (6+), партнёр спрашивает 2♣; 2♣ = трефы и старшая масть; 2♦ = бубны и мажор; 2♥ = обе старшие; 2♠ = только пики (натурально). Партнёр пасует с терпимостью или называет следующую масть (пас или поправка). Заменяет Каппеллетти."],"jtr":["Трансфер Якоби","После 1БК 2♦ просит открывшего назвать червы, а 2♥ — пики, чтобы играла сильная рука. С четырёхкартной поддержкой и максимумом (17) открывший делает суперакцепт на уровне трёх. После трансфера новая масть на уровне трёх натуральна и форсирует до гейма."],"sys":["Заявка системы","Искусственная заявка выбранной системы (Precision, Польская трефа, Мульти 2♦): что она показывает, написано выше. Система выбирается на главной странице (Ваша система) или в Настройках."],"bw":["Блэквуд","4БК спрашивает тузы: 5♣ = 0 или 4, 5♦ = 1, 5♥ = 2, 5♠ = 3."],"q":["Количественные 4БК","После заявки в бескозырной 4БК не спрашивает тузы, а приглашает в шлем. С максимумом партнёр говорит 6БК."],"nego":["Негативная контра","Когда партнёр открыл, а соперник вмешался, контра не штрафная: она показывает четыре карты в незаявленном мажоре и силу для заявки."],"takeout":["Вызывная контра","Контра открытия: сила на открытие, короткость в их масти и поддержка в остальных мастях. Партнёр обязан заявить."],"weak2":["Слабые два","Открытие 2♦/2♥/2♠: хорошая шестёрка, 5-10 О. Блокирующее открытие."],"strong2c":["Сильные 2♣","Открытие 2♣: 22+ О или равная игровая сила, искусственно и форсирует до гейма. 2♦ — ответ-ожидание. После 2♣–2♦–2♥/2♠ 3♣ — второй негатив (0-3 О); 2♣–2♦–2БК (22-24) торгуется как открытие 2БК (Стейман и трансферы)."],"cue":["Кью-бид","Заявка в масти соперников не натуральна: показывает поддержку партнёра с инвитом или сильнее и форсирует."],"nt1":["Открытие 1БК","15-17 О, равномерный расклад."],"pre":["Блок","Открытие на уровне трёх или четырёх: длинная масть (7+) и слабая рука, отнимает у соперников пространство торговли."],"runout":["Бегство после контры на 1БК","Когда наши 1БК контрированы, слабый отвечающий убегает в масть из 5+ карт; реконтра показывает силу (9+)."]};
var SYS_T = window.SYS_T || {}; SYS_T["ru"] = {"twoone":"Пятые мажоры, 1БК 15-17, слабые два, сильные 2♣. Новая масть на уровне двух у непасовавшего отвечающего — форсинг до гейма; 1БК на мажор форсирует.","sayc":"Пятые мажоры, 1БК 15-17, слабые два, сильные 2♣, трансферы Якоби и Стейман, Блэквуд. Новая масть на уровне двух форсирует на круг (10+); 1БК на мажор 6-10 и не форсирует; прыжки в новой масти сильные.","acol":"Четвёртые мажоры, слабые 1БК (12-14), сильные 2♣ (23+ или форсинг до гейма), слабые два в ♦ ♥ ♠, инвитные повышения (повышение обещает четыре карты), 2БК 20-22, Стейман и трансферы, RKCB.","sef":"Système d’Enseignement Français: пятые мажоры, «лучшая младшая» 1♣/1♦, 1БК 15-17, сильные форсирующие 2♣, искусственные 2♦ — форсинг до гейма, слабые 2♥/2♠. Новая масть на уровне двух форсирует на круг; RKCB.","precision":"Сильная трефа: 1♣ = 16+ любой расклад (искусственно, форсинг; 1♦ = негатив 0-7). Прочие открытия 11-15: 1♦ 2+ ♦ (сборное), 1♥/1♠ 5+, 1БК 13-15, 2♣ 6+ ♣ (или 5♣ + четвёртый мажор), 2♦ трёхмастка с короткими бубнами (4-4-1-4 / 4-4-0-5), слабые 2♥/2♠.","polish":"Wspólny Język: 1♣ = (а) 12-14 равномерно, (б) 15+ с длинными трефами или (в) 18+ любая (1♦ = негатив 0-7 или ожидание). 1♦ 4+ ♦ неравномерно, 1♥/1♠ 5+, 1БК 15-17, 2♣ 6+ ♣ 11-15, 2♦ Мульти (слабые два в ♥ или ♠), слабые 2♥/2♠."};
